import { build } from 'esbuild';
import assert from 'node:assert/strict';
import { builtinModules } from 'node:module';
import { readFile, writeFile, mkdir, readdir } from 'node:fs/promises';
import { dirname, resolve, relative, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const output = resolve(here, '../../lib/vendor');
await mkdir(output, { recursive: true });
const result = await build({
  absWorkingDir: here,
  entryPoints: ['entry.js'],
  outfile: join(output, 'pi-ai.js'),
  bundle: true,
  platform: 'node',
  target: 'node22.19',
  format: 'esm',
  minify: false,
  legalComments: 'eof',
  metafile: true,
  banner: { js: '// Generated by scripts/vendor/build.mjs. See pi-ai.LICENSES.txt.\nimport { createRequire as vendorCreateRequire } from "node:module";\nconst require = vendorCreateRequire(import.meta.url);' },
});
for (const entry of Object.values(result.metafile.outputs)) {
  for (const dependency of entry.imports) {
    assert.ok(dependency.path.startsWith('node:') || builtinModules.includes(dependency.path), `Unbundled runtime dependency: ${dependency.path}`);
  }
}
const inputs = Object.keys(result.metafile.inputs);
if (inputs.some(path => /node_modules\/(?:@google\/genai|protobufjs|@aws-sdk)\//.test(path))) {
  throw new Error('Unneeded Google/Protobuf/Bedrock runtime entered the bundle');
}
const packages = [...new Set(inputs.flatMap(path => {
  const match = path.match(/node_modules\/((?:@[^/]+\/)?[^/]+)\//);
  return match ? [match[1]] : [];
}))].sort();
const licenses = [];
const versions = {};
for (const name of packages) {
  const dir = join(here, 'node_modules', name);
  const pkg = JSON.parse(await readFile(join(dir, 'package.json'), 'utf8'));
  versions[name] = pkg.version;
  const files = (await readdir(dir)).filter(file => /^(LICENSE|COPYING|NOTICE)(\.|$)/i.test(file));
  if (!files.some(file => /^(LICENSE|COPYING)(\.|$)/i.test(file)) && !["@earendil-works/pi-ai", "standardwebhooks"].includes(name)) throw new Error(`Missing license: ${name}`);
  const texts = await Promise.all(files.map(file => readFile(join(dir, file), 'utf8')));
  if (name === '@earendil-works/pi-ai') texts.push(await readFile(join(here, 'pi-ai.LICENSE'), 'utf8'));
  if (name === 'standardwebhooks') texts.push(await readFile(join(here, 'standardwebhooks.LICENSE'), 'utf8'));
  const note = name === 'standardwebhooks' ? '\nThe npm manifest declares MIT; the upstream repository at the published gitHead supplies the Apache-2.0 text reproduced below.\n' : '';
  licenses.push(`## ${name}@${pkg.version} (npm manifest: ${pkg.license})\n${note}\n${texts.join('\n\n')}`);
}
await writeFile(join(output, 'pi-ai.LICENSES.txt'), licenses.join('\n\n'));
await writeFile(join(output, 'pi-ai.build.json'), JSON.stringify({
  generatedBy: 'scripts/vendor/build.mjs',
  packages: versions,
  inputs,
  bytes: result.metafile.outputs[Object.keys(result.metafile.outputs)[0]].bytes,
}, null, 2) + '\n');
console.log(`Bundled ${packages.length} runtime packages into ${relative(here, output)}`);

const original = await import('@earendil-works/pi-ai/providers/all');
const bundled = await import('../../lib/vendor/pi-ai.js');
assert.deepEqual(bundled.getBuiltinModels('opencode-go'), original.getBuiltinModels('opencode-go'));
console.log('OpenCode Go catalog matches upstream exactly');
